nces to purchase", "recommended number of reserved nodes to purchase", "reserved instance id", "resource record set id", "s3 storage (gb)", "security group ids", "time near maximum", "time updated", "ttl", "upfront cost of reserved instances", "upfront cost of reserved nodes", "usage (usd per day)", "user name (iam or root)", "zone", "function arn", "max daily error rate", "date for max error rate", "average daily error rate", "lost daily compute cost", "current day invokes", "current day error rate", "average daily invokes", "last refresh time", "max daily timeout rate", "date of max daily timeout rate", "average daily timeout rate", "function timeout setting", "current day timeout rate", "runtime", "days to deprecation", "deprecation date", "resource", "workload type", "workload last modified date", "workload started date", "number of questions answered for performance", "number of hris resolved for performance", "total number of questions in performance pillar", "number of identified hris for performance", "reviewer name", "workload arn", "workload name", "number of hris resolved for reliability", "total number of questions in reliability pillar", "number of questions answered for reliability", "number of identified hris for reliability", "number of hris resolved for security", "total number of questions in security pillar", "number of questions answered for security", "number of identified hris for security", "number of hris resolved for cost optimization", "total number of questions in cost optimization pillar", "number of questions answered for cost optimization", "number of identified hris for cost optimization", "cluster name", "checkname" AS "Check Name", CASE WHEN "checkname" = 'Idle Load Balancers' THEN "load balancer name" WHEN "checkname" = 'Amazon RDS Idle DB Instances' THEN "db instance name" WHEN "checkname" = 'Low Utilization Amazon EC2 Instances' THEN "instance id" WHEN "checkname" = 'Unassociated Elastic IP Addresses' THEN "ip address" WHEN "checkname" = 'Underutilized Amazon EBS Volumes' THEN "volume id" WHEN "checkname" = 'Underutilized Amazon Redshift Clusters' THEN "cluster" WHEN "checkname" = 'Amazon EBS Public Snapshots' THEN "volume id" WHEN "checkname" = 'Amazon RDS Public Snapshots' THEN "db instance or cluster id" WHEN "checkname" = 'AWS Lambda Functions with High Error Rates' THEN "function arn" WHEN "checkname" = 'AWS Lambda Functions Using Deprecated Runtimes' THEN "function arn" WHEN "checkid" = 'Wxdfp4B1L1' OR "checkid" = 'Wxdfp4B1L2' OR "checkid" = 'Wxdfp4B1L3' OR "checkid" = 'Wxdfp4B1L4' THEN "workload arn" ELSE (COALESCE("resourceid", '')  || COALESCE(CASE WHEN "accountname" = '' OR "accountname" IS NULL THEN "accountid" ELSE (COALESCE("accountname", '')  || COALESCE(': ', '')  || COALESCE("accountid", '')) END, '')) END AS "Resource Name", from_unixtime(cast(substr(cast(case when regexp_like("timestamp", '^-?\d+$') then cast("timestamp" as bigint) else null end as varchar), 1, 10) AS bigint)) AS "Datetime", CASE WHEN "accountname" = '' OR "accountname" IS NULL THEN "accountid" ELSE (COALESCE("accountname", '')  || COALESCE(': ', '')  || COALESCE("accountid", '')) END AS "Account", CASE WHEN "checkname" = 'Idle Load Balancers' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Amazon RDS Idle DB Instances' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings (on demand)", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings (on demand)", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Low Utilization Amazon EC2 Instances' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Underutilized Amazon EBS Volumes' THEN case when regexp_like(REPLACE(REPLACE("monthly storage cost", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("monthly storage cost", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'Underutilized Amazon Redshift Clusters' THEN case when regexp_like(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("estimated monthly savings", '$', ''), ',', '') as double) else null end WHEN "checkname" = 'AWS Lambda Functions with High Error Rates' THEN case when regexp_like(REPLACE(REPLACE("lost daily compute cost", '$', ''), ',', ''), '^-?\d+(\.\d*)?$') then cast(REPLACE(REPLACE("lost daily compute cost", '$', ''), ',', '') as double) else null end * 30 ELSE NULL END AS "Estimated Monthly Savings Numeric", CASE WHEN "status" = 'error' THEN 'Red' WHEN "status" = 'warning' THEN 'Yellow' WHEN "status" = 'ok' THEN 'Green' ELSE "status" END AS "Status", CASE WHEN "category" = 'cost_optimizing' THEN 'Cost Optimizing' WHEN "category" = 'fault_tolerance' THEN 'Fault Tolerance' WHEN "category" = 'security' THEN 'Security' WHEN "category" = 'performance' THEN 'Performance' WHEN "category" = 'service_limits' THEN 'Service Limits' ELSE "category" END AS "Category", (COALESCE("resourceid", '')  || COALESCE(CASE WHEN "accountname" = '' OR "accountname" IS NULL THEN "accountid" ELSE (COALESCE("accountname", '')  || COALESCE(': ', '')  || COALESCE("accountid", '')) END, '')) AS "Resource Id"
